export function unifiedDiffLines(aLines, bLines) {
  const sm = new SequenceMatcher(aLines, bLines);
  const result = [];
  let started = false;
  for (const group of sm.getGroupedOpcodes(3)) {
    if (!started) {
      started = true;
      result.push('--- ');
      result.push('+++ ');
    }
    const first = group[0], last = group[group.length-1];
    result.push('@@ -' + formatRangeUnified(first[1], last[2]) + ' +' + formatRangeUnified(first[3], last[4]) + ' @@');
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) result.push(' ' + aLines[i]);
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (let i = i1; i < i2; i++) result.push('-' + aLines[i]);
      }
      if (tag === 'replace' || tag === 'insert') {
        for (let j = j1; j < j2; j++) result.push('+' + bLines[j]);
      }
    }
  }
  return result;
}
